window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-2bed4ec6a2620d79"]={"versions": [{"id": "FIG-2bed4ec6a2620d79", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Metamodell-Instanzdiagramm zur Spezifikation der AUTOSAR-XML-Persistenzregeln. Das Diagramm stellt die metamodellbasierte Repräsentation eines nicht-aggregierenden Klassenattributs (<code>aggregation = none</code>) im Kontext des AUTOSAR-UML-Metamodells dar. Im oberen Bereich wird die Entwurfsmodell-Sicht gezeigt, im unteren Bereich die entsprechende Instanziierung der UML-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im oberen Bereich befinden sich die Entwurfsklassen:</p>\n<ul class=\"fig-list\"><li>Klasse <code>D</code> mit dem Attribut <code>+ theB: B* [0..*]</code>.\n</li><li>Klasse <code>B</code> als referenzierter Zieltyp.\n</li></ul>\n<p class=\"fig-p\">Im unteren Bereich befinden sich die Instanzen der Metaklassen:</p>\n<ul class=\"fig-list\"><li>Instanz <code>:Class</code> mit <code>name = D</code> (repräsentiert Klasse <code>D</code>).\n</li><li>Instanz <code>:Class</code> mit <code>name = B</code> (repräsentiert Klasse <code>B</code>).\n</li><li>Instanz <code>:Property</code> mit den Slot-Werten:\n<ul class=\"fig-list\"><li><code>upper = unbounded</code>\n</li><li><code>lower = 0</code>\n</li><li><code>aggregation = none</code>\n</li><li><code>name = theB</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Kompositionsbeziehung (schwarze Raute) von <code>:Class (D)</code> zu <code>:Property</code> mit Rollenbezeichnung <code>+ownedAttribute</code>.\n</li><li>Gerichtete Assoziation von <code>:Property</code> zu <code>:Class (B)</code> mit Rollenbezeichnung <code>+type</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodellierungsdiagramm; kein dynamischer Sequenzablauf vorhanden. Das Diagramm spezifiziert die semantische Abbildung eines UML-Attributs ohne Aggregation (<code>aggregation = none</code>) auf Instanzen von <code>Property</code> und <code>Class</code> im AUTOSAR-Metamodell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Abbildungsregel für AUTOSAR-XML-Serialisierung und Modellpersistenz: Ein Attribut mit <code>aggregation = none</code> repräsentiert eine Referenzbeziehung (nicht-besitzende Assoziation/Referenz) statt einer geschachtelten Elementkomposition. In der XML-Darstellung führt dies zu einer typischen Referenzierung (z. B. über Pfad- oder Namensverweise wie Ref/URI) anstelle einer direkten Schachtelung im XML-Schema. Implementierer von Serialisierungs-, Deserialisierungs- und Metamodell-Generatoren müssen <code>Property</code>-Elemente mit <code>aggregation = none</code> als externe Verweise auflösen und abbilden.</p>"}, {"id": "FIG-4f006635cc301b98", "releases": ["R3.0.7", "R3.1.5", "R3.2.3", "R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm und Metamodell-Instanzdiagramm zur Spezifikation der AUTOSAR-XML-Persistenzregeln. Das Diagramm stellt die metamodellbasierte Repräsentation eines nicht-aggregierenden Klassenattributs (<code>aggregation = none</code>) im Kontext des AUTOSAR-UML-Metamodells dar. Im oberen Bereich wird die Entwurfsmodell-Sicht gezeigt, im unteren Bereich die entsprechende Instanziierung der UML-Metaklassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im oberen Bereich befinden sich die Entwurfsklassen:</p>\n<ul class=\"fig-list\"><li>Klasse <code>D</code> mit dem Attribut <code>+ theB: B* [0..*]</code>.\n</li><li>Klasse <code>B</code> als referenzierter Zieltyp.\n</li></ul>\n<p class=\"fig-p\">Im unteren Bereich befinden sich die Instanzen der Metaklassen:</p>\n<ul class=\"fig-list\"><li>Instanz <code>:Class</code> mit <code>name = D</code> (repräsentiert Klasse <code>D</code>).\n</li><li>Instanz <code>:Class</code> mit <code>name = B</code> (repräsentiert Klasse <code>B</code>).\n</li><li>Instanz <code>:Property</code> mit den Slot-Werten:\n<ul class=\"fig-list\"><li><code>upper = unbounded</code>\n</li><li><code>lower = 0</code>\n</li><li><code>aggregation = none</code>\n</li><li><code>name = theB</code>\n</li></ul>\n</li></ul>\n<p class=\"fig-p\">Beziehungen:</p>\n<ul class=\"fig-list\"><li>Kompositionsbeziehung (schwarze Raute) von <code>:Class (D)</code> zu <code>:Property</code> mit Rollenbezeichnung <code>+ownedAttribute</code>.\n</li><li>Gerichtete Assoziation von <code>:Property</code> zu <code>:Class (B)</code> mit Rollenbezeichnung <code>+type</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Struktur- und Metamodellierungsdiagramm; kein dynamischer Sequenzablauf vorhanden. Das Diagramm spezifiziert die semantische Abbildung eines UML-Attributs ohne Aggregation (<code>aggregation = none</code>) auf Instanzen von <code>Property</code> und <code>Class</code> im AUTOSAR-Metamodell.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Abbildungsregel für AUTOSAR-XML-Serialisierung und Modellpersistenz: Ein Attribut mit <code>aggregation = none</code> repräsentiert eine Referenzbeziehung (nicht-besitzende Assoziation/Referenz) statt einer geschachtelten Elementkomposition. In der XML-Darstellung führt dies zu einer typischen Referenzierung (z. B. über Pfad- oder Namensverweise wie Ref/URI) anstelle einer direkten Schachtelung im XML-Schema. Implementierer von Serialisierungs-, Deserialisierungs- und Metamodell-Generatoren müssen <code>Property</code>-Elemente mit <code>aggregation = none</code> als externe Verweise auflösen und abbilden.</p>"}], "trans": [{"from": "FIG-2bed4ec6a2620d79", "to": "FIG-4f006635cc301b98", "fr": "R2.1.20", "tr": "R3.0.7", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
